Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public static class FilesNative{[DllImport("user32.dll")]public static extern bool SetWindowPos(IntPtr h,IntPtr a,int x,int y,int w,int z,uint f);}'
$output=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $output){throw 'Fresh output required'};[IO.Directory]::CreateDirectory($output)|Out-Null
$data=Join-Path $output 'isolated-data';$stateFile=Join-Path $data 'window-state.json';$process=$null;$checks=0
function State{try{$r=[IO.StreamReader]::new([IO.File]::Open($stateFile,'Open','Read',([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)));try{return $r.ReadToEnd()|ConvertFrom-Json}finally{$r.Dispose()}}catch [IO.IOException]{return $null}}
function Await([scriptblock]$test,[string]$name){$end=[DateTime]::UtcNow.AddSeconds(45);do{if(&$test){return};if($process.HasExited){throw ('EXIT '+$name)};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow -lt $end);throw ('TIMEOUT '+$name)}
function Check([bool]$value,[string]$name){if(-not $value){throw ('FILES_FAIL '+$name)};$script:checks++}
try{
 $start=[Diagnostics.ProcessStartInfo]::new([IO.Path]::GetFullPath($Executable));$start.UseShellExecute=$false;$start.WindowStyle='Hidden';$start.Arguments='--data-dir "'+$data+'" --diagnostics --capture --text-scale '+$TextScale
 $process=[Diagnostics.Process]::Start($start);Await {(State).ready -and (State).revision -eq (State).captureRevision} 'ready';$root=[Windows.Automation.AutomationElement]::FromHandle([IntPtr][long](State).hwnd);[FilesNative]::SetWindowPos([IntPtr][long](State).hwnd,[IntPtr]::Zero,0,0,$Width,$Height,0x14)|Out-Null
