 function Reach([string]$id){if($id.StartsWith('Files') -and $id -notin @('FilesGenerate','FilesExecute','FilesDiscard','FilesJobs','FilesConsent','FilesFullPaths','FilesEntries','FilesPurgePhrase')){$viewport=Find 'FilesSetupScroll';$pattern=$null;if($viewport -and $viewport.TryGetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern,[ref]$pattern) -and $pattern.Current.VerticallyScrollable){$pattern.SetScrollPercent(-1,0)}};Await {try{$e=Find $id;if(-not $e -or -not $e.Current.IsEnabled){return $false};$rect=$e.Current.BoundingRectangle;$minimum=if($id -eq 'PrimaryButton' -or $id -eq 'FilesPurgePhrase'){28}else{30};$parent=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($e);for($i=0;$i -lt 18 -and $parent;$i++){if($parent.Current.ProcessId -ne $process.Id){break};$sp=$null;if($parent.TryGetCurrentPattern([Windows.Automation.ScrollPattern]::Pattern,[ref]$sp)){$viewport=$parent.Current.BoundingRectangle;if($rect.Height -ge $minimum -and $rect.Top -ge $viewport.Top-1 -and $rect.Bottom -le $viewport.Bottom+1){}elseif($sp.Current.VerticallyScrollable){$direction=if($rect.Height -gt 0 -and ($rect.Top -lt $viewport.Top -or ($rect.Height -lt $minimum -and $rect.Top -le $viewport.Top+1))){[Windows.Automation.ScrollAmount]::SmallDecrement}else{[Windows.Automation.ScrollAmount]::SmallIncrement};if($e.Current.IsOffscreen -and $sp.Current.VerticalScrollPercent -ge 99){$sp.SetScrollPercent(-1,0)}else{$sp.Scroll([Windows.Automation.ScrollAmount]::NoAmount,$direction)};return $false}};$parent=[Windows.Automation.TreeWalker]::ControlViewWalker.GetParent($parent)};$bounds=$root.Current.BoundingRectangle;return -not $e.Current.IsOffscreen -and $rect.Height -ge $minimum -and $rect.Top -ge $bounds.Top -and $rect.Bottom -le $bounds.Bottom}catch{if($_.Exception -is [Windows.Automation.ElementNotAvailableException] -or $_.Exception.InnerException -is [Windows.Automation.ElementNotAvailableException]){return $false};throw}} ('reachable '+$id)}
 function Click([string]$id){Reach $id;Await {$candidate=Find $id;$pattern=$null;if($candidate -and $candidate.Current.IsEnabled -and $candidate.TryGetCurrentPattern([Windows.Automation.InvokePattern]::Pattern,[ref]$pattern)){$script:readyInvoke=$pattern;return $true};return $false} ('stable invoke '+$id);$script:readyInvoke.Invoke();$script:checks++;if($id.StartsWith('Nav')){$page=$id.Substring(3);Await {$s=State;return $s.workspace.page -eq $page -and -not $s.workspace.files.loading -and -not $s.workspace.management.loading -and $s.revision -eq $s.captureRevision} ('settled '+$page)};if($id.StartsWith('FilesMode')){$mode=$id.Substring(9);Await {$s=State;return $s.workspace.files.mode -eq $mode -and -not $s.workspace.files.loading -and $s.revision -eq $s.captureRevision} ('settled mode '+$mode)}}
 function SetText([string]$id,[string]$value){Reach $id;Await {$candidate=Find $id;$pattern=$null;if($candidate -and $candidate.TryGetCurrentPattern([Windows.Automation.ValuePattern]::Pattern,[ref]$pattern)){$script:readyValue=$pattern;return $true};return $false} ('stable value '+$id);$script:readyValue.SetValue($value)}
