 function Checkpoint([string]$name){Await {$s=State;return -not $s.workspace.files.loading -and -not $s.workspace.files.writing -and $s.revision -eq $s.captureRevision} ('capture '+$name);$s=State;@{name=$name;capture=$s.captures[-1]}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $output 'checkpoints.jsonl')}
