 function ExecuteReview{Reach 'FilesConsent';(Find 'FilesConsent').GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern).Toggle();Await {(State).workspace.files.canExecute} 'consent gate';Click 'FilesExecute';Click 'PrimaryButton';JobsDone}
