 SetText 'GalleryImportPath' $import;Click 'GalleryImportStart';JobsDone;Click 'NavGallery';SetText 'GallerySearch' 'a.png';Await {$g=(State).workspace.gallery; $g.queryLength -eq 5 -and $null -ne $g.ids -and @($g.ids).Count -gt 0 -and $g.ids[0] -gt 1000001 -and -not (State).workspace.gallery.loading} 'imported synthetic image';$imageId=(State).workspace.gallery.ids[0];Await {$null -ne (Find ('GalleryImage'+$imageId))} 'imported tile';(Find ('GalleryImage'+$imageId)).GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select();Await {(State).workspace.gallery.selectedCount -eq 1} 'selected scope';Click 'NavOrganize';Await {-not (State).workspace.files.loading} 'form ready';Choose 'FilesClassification' '文件格式'
 $reviewDb=@(Get-ChildItem -LiteralPath $data -Recurse -File -Filter 'file-reviews.sqlite3')[0].FullName;$lockReady=Join-Path $output 'lock-ready';$lockRelease=Join-Path $output 'lock-release';$lockScript=Join-Path $PSScriptRoot 'ReviewLockFixture.py'
 $lockStart=[Diagnostics.ProcessStartInfo]::new([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../../.venv-build/Scripts/python.exe')));$lockStart.UseShellExecute=$false;$lockStart.WindowStyle='Hidden';foreach($arg in @($lockScript,$reviewDb,$lockReady,$lockRelease)){$lockStart.ArgumentList.Add($arg)};$lockProcess=[Diagnostics.Process]::Start($lockStart);Await {Test-Path -LiteralPath $lockReady} 'synthetic response gate'
 $destination=Join-Path $output 'synthetic-sorted';SetText 'FilesDestination' $destination;Click 'FilesGenerate';Await {(State).workspace.files.writing} 'submission waiting';SetText 'FilesDestination' ($destination+'-newer');[IO.File]::WriteAllText($lockRelease,'release');Check ($lockProcess.WaitForExit(10000) -and $lockProcess.ExitCode -eq 0) 'synthetic lock released';Await {-not (State).workspace.files.writing} 'late submission response';Check ((Find 'FilesDestination').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value -eq ($destination+'-newer')) 'late response preserves new input';Check (-not (State).workspace.files.previewInFlight -and -not (Find 'FilesExecute').Current.IsEnabled) 'old preview cannot retain consent or trap generate';Click 'FilesJobs';JobsDone;Click 'NavOrganize';Await {-not (State).workspace.files.loading} 'return after old preview';Choose 'FilesClassification' '文件格式';SetText 'FilesDestination' $destination;Click 'FilesGenerate';Await {(State).workspace.files.reviewState -eq 'ready'} 'saved move preview';Check (-not (Find 'FilesExecute').Current.IsEnabled) 'confirmation required';Checkpoint 'move-preview'
 Click 'FilesTogglePaths';Reach 'FilesFullPaths';Check ((Find 'FilesFullPaths').Current.BoundingRectangle.Height -ge 48) 'readable path viewport';Await {(Find 'FilesFullPaths').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value.Contains('a.png')} 'selected paths';$paths=(Find 'FilesFullPaths').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current.Value -split '\r\n|\r|\n';$source=$paths[1];$target=$paths[3];Check ((Test-Path -LiteralPath $source) -and -not (Test-Path -LiteralPath $target)) 'preview has no file effect';$hash=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash
 SetText 'FilesDestination' ($destination+'-changed');Check (-not (Find 'FilesExecute').Current.IsEnabled) 'editing invalidates confirmation';SetText 'FilesDestination' $destination;Click 'FilesGenerate';Await {(State).workspace.files.reviewState -eq 'ready'} 'fresh preview'
 ExecuteReview;Check (-not (Test-Path -LiteralPath $source) -and (Test-Path -LiteralPath $target)) 'native confirmed move';Check ((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -eq $hash) 'moved bytes verified'
 Click 'NavOrganize';Await {-not (State).workspace.files.loading} 'history reloaded';Click 'FilesUndoPreview';Await {(State).workspace.files.reviewState -eq 'ready' -and (State).workspace.files.reviewKind -eq 'organize_undo'} 'undo preview';Checkpoint 'undo-preview';ExecuteReview;Check ((Test-Path -LiteralPath $source) -and -not (Test-Path -LiteralPath $target)) 'native undo restored';Check ((Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash -eq $hash) 'undo bytes unchanged'
