 Click 'NavDuplicates';Click 'FilesModequarantine';Await {-not (State).workspace.files.loading} 'purge history';Click 'FilesPurgePreview';Await {(State).workspace.files.reviewState -eq 'ready' -and (State).workspace.files.reviewKind -eq 'duplicate_purge'} 'independent purge preview';Checkpoint 'purge-preview';(Find 'FilesConsent').GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern).Toggle();Click 'FilesExecute';Await {$null -ne (Find 'FilesPurgePhrase')} 'purge phrase';Check (-not (Find 'PrimaryButton').Current.IsEnabled) 'empty purge phrase rejected';SetText 'FilesPurgePhrase' 'wrong';Check (-not (Find 'PrimaryButton').Current.IsEnabled) 'wrong purge phrase rejected';SetText 'FilesPurgePhrase' '永久清空';Click 'PrimaryButton';JobsDone;Check (@(Get-ChildItem -LiteralPath $import -File -Filter '*.png').Count -eq 2) 'permanent purge retains keeper and protected original';$keepers=@(Get-ChildItem -LiteralPath $import -File -Filter '*.png');foreach($keeper in $keepers){Check ((Get-FileHash -LiteralPath $keeper.FullName).Hash -eq $duplicateHash) 'keeper unchanged after permanent purge'}
